import{_ as o,l as p,o as e,c as s,v as t,p as l,x as r,d as n,i as P,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"PTP / GPS 对时","description":"","frontmatter":{"title":"PTP / GPS 对时","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ptp-gps-sync.md","filePath":"quant/ptp-gps-sync.md","lastUpdated":1789023840000}'),E={name:"quant/ptp-gps-sync.md"};function c(h,a,T,B,_,u){const i=p("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ptp-gps-对时" tabindex="-1">PTP / GPS 对时 <a class="header-anchor" href="#ptp-gps-对时" aria-label="Permalink to &quot;PTP / GPS 对时&quot;">​</a></h1><div class="epigraph"><p>两台引擎的纳秒时间戳只有在同步到同一时间基之后才能相减。未校准的「领先 50 微秒」可能只是两台钟差了 50 微秒。</p><footer>—— 据 IEEE 1588 PTP 与卫星授时的公开技术标准；对照 MiFID II RTS 与 FINRA 对业务时钟同步精度的监管要求</footer></div><p><a href="/quant/exchange-broker-clocks">交易所时间戳与经纪商时间戳</a>要求读懂字段。本课的缺口是：不同场所、SIP、经纪商的匹配时间即使都叫 UTC，振荡器仍会漂。GPS 提供时间基，PTP（IEEE 1588）在机房内分发。监管（如 MiFID II 的 RTS 对时钟精度、FINRA 对业务时钟）把同步从工程偏好变成合规。本课写对时如何进入跨所研究与 NBBO 构造，不写如何建设机房授时，也不写如何利用残留钟差去交易。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跨所领先滞后、合成 NBBO、延迟套利检验，都要比较 \\(t_A\\) 与 \\(t_B\\)。若 A 所的钟快 30 微秒，A 会在所有研究里「领先」。Hasbrouck 信息份额对时钟误差敏感。缺口是在合并前得到一个共同时间基，并报告残留误差上限。监管给出的最大偏离（例如相对 UTC 的若干微秒）是合规上限，不是你样本里的实际误差。研究应尽量用交易所提供的同步质量字段或官方对时说明，而不是假设合规即无误差。</p><p>SIP 与直连的分叉，一部分是真延迟，一部分是两套钟。不对时，分叉被高估或低估。系统课里 <code>exch_ts - local_ts</code> 更是钟差加传输；要分解必须先把本地钟也同步，否则延迟预算的测量无定义。</p><h3 id="gps、ptp、ntp-不是同一精度" tabindex="-1">GPS、PTP、NTP 不是同一精度 <a class="header-anchor" href="#gps、ptp、ntp-不是同一精度" aria-label="Permalink to &quot;GPS、PTP、NTP 不是同一精度&quot;">​</a></h3><p>NTP 在公网是毫秒级，不够高频跨所。GPS 提供 UTC 参照，天线与接收质量影响。PTP 在良好网络下可达亚微秒到微秒。研究不需要自己达到交易所精度，但需要知道数据源声称的精度，并在结论里把「小于该精度的领先」视为无法识别。把 3 微秒的领先写成价格发现，当馈送精度是 50 微秒时，是假结果。</p><p><span class="marginnote">卫星授时有闰秒、天线遮挡、欺骗干扰等已知问题。交易场所通常有冗余。研究侧把「GPS」三个字写进论文，不等于样本已校准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合并多所数据前：读取各源关于时钟同步的文档与质量标志；若有交易所间的官方偏移，应用偏移。没有偏移时，用极度活跃的交叉上市或期货现货对，估计固定偏移（注意这会把真领先吸进偏移——只能当敏感性，不能当真理）。报告：识别阈 = 声称精度之和。小于阈值的领先滞后不解释为经济。</p><p>本地研究集群若用于到达时间，应用 PTP 或至少 GPS，并记录与 UTC 的偏移日志。偏移突变日应从延迟样本中剔除。这与序号缺口一样，是质量事件。</p><h3 id="对时与监管时间戳" tabindex="-1">对时与监管时间戳 <a class="header-anchor" href="#对时与监管时间戳" aria-label="Permalink to &quot;对时与监管时间戳&quot;">​</a></h3><p>MiFID II 等要求报告交易的时钟同步到规定精度，精度随交易类型变化。这使欧洲磁带比早期美股秒级 TAQ 更可比，仍不意味着你可以解释亚微秒。TRACE 的报告时钟是经销商业务钟，精度与股票引擎不可比，见最后一课。不要把股票 PTP 的语言套到债券打印上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步误差是加在真事件时间上的测量误差。领先滞后回归把测量误差当成因果。信息份额把先动的钟当成信息源。NBBO 若用未校准时间取 \\(\\max b\\)、\\(\\min a\\)，可能把「尚未发生」的报价拼进去，造成虚假交叉。对时是市场数据的识别条件，就像方向分类是价差分解的识别条件。</p><p><span class="marginnote">加密各所自行授时，跨所「领先」文献尤其容易是钟差。没有共同 GPS 基，不要做毫秒级价格发现排序。</span></p>',17)),(e(),l(d,null,{default:r(()=>[P(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20LR%0A%20%20GPS%5B%22GPS%20%2F%20UTC%20%E6%97%B6%E9%97%B4%E5%9F%BA%22%5D%20--%3E%20PTP%5B%22%E6%9C%BA%E6%88%BF%20PTP%20%E5%88%86%E5%8F%91%22%5D%0A%20%20PTP%20--%3E%20A%5B%22%E5%9C%BA%E6%89%80%20A%20%E5%8C%B9%E9%85%8D%E9%92%9F%22%5D%0A%20%20PTP%20--%3E%20B%5B%22%E5%9C%BA%E6%89%80%20B%20%E5%8C%B9%E9%85%8D%E9%92%9F%22%5D%0A%20%20A%20--%3E%20CMP%5B%22%E5%8F%AF%E6%AF%94%E8%BE%83%E7%9A%84%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%22%5D%0A%20%20B%20--%3E%20CMP%0A%20%20ERR%5B%22%E6%AE%8B%E7%95%99%E9%92%9F%E5%B7%AE%E4%B8%8A%E9%99%90%22%5D%20--%3E%20CMP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="识别阈以下的领先不做经济解释" tabindex="-1">识别阈以下的领先不做经济解释 <a class="header-anchor" href="#识别阈以下的领先不做经济解释" aria-label="Permalink to &quot;识别阈以下的领先不做经济解释&quot;">​</a></h3><p>两套馈送声称精度之和，构成可识别的最小时差。把 3 微秒的领先写成价格发现，当精度是 50 微秒时，是测量误差叙事。结论应在阈值之上稳健。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论授时攻击。研究结论应在残留误差下稳健。下一课在已对时（或已声明未对时）的前提下构造 NBBO。</p><p><span class="marginnote">用交叉上市估计固定钟差，会把真的领先吸进偏移。该方法只能当敏感性，不能当已校准的时间基。监管合规上限同样不是样本实际误差。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨所时间相减的前提是共同时间基；否则领先可能是钟差。</li><li>识别阈由馈送声称精度决定，阈下不做经济解释。</li><li>GPS 提供基，PTP 分发；NTP 不够高频跨所。</li><li>合规上限 ≠ 样本实际误差，要读质量字段。</li><li>债券与加密的时钟精度通常不可与股票引擎比。</li><li>出处：IEEE 1588；MiFID II 时钟同步监管技术标准；FINRA 业务时钟要求；Hasbrouck 对多市场度量的数据前提。</li></ul>',7))])}const S=o(E,[["render",c]]);export{m as __pageData,S as default};
